import{_ as s,o as e,c as n,a2 as o,j as a,a as p}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 2 课 怎么跟我说：像点菜一样说清楚","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第2课 怎么跟我说：像点菜一样说清楚.md","filePath":"easy/第2课 怎么跟我说：像点菜一样说清楚.md"}'),l={name:"easy/第2课 怎么跟我说：像点菜一样说清楚.md"};function r(i,t,d,c,h,u){return e(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-2-课-怎么跟我说-像点菜一样说清楚" tabindex="-1">第 2 课 怎么跟我说：像点菜一样说清楚 <a class="header-anchor" href="#第-2-课-怎么跟我说-像点菜一样说清楚" aria-label="Permalink to &quot;第 2 课 怎么跟我说：像点菜一样说清楚&quot;">​</a></h1><h2 id="最关键的比喻-点菜" tabindex="-1">最关键的比喻：点菜 <a class="header-anchor" href="#最关键的比喻-点菜" aria-label="Permalink to &quot;最关键的比喻：点菜&quot;">​</a></h2><p>你去饭馆，会说&quot;来一份宫保鸡丁&quot;——不会说&quot;给我弄点吃的&quot;。</p><p>跟我说任务，跟点菜一模一样：</p><table tabindex="0"><thead><tr><th>点菜</th><th>跟我说任务</th></tr></thead><tbody><tr><td>菜名</td><td>你要什么结果（写一份周报）</td></tr><tr><td>口味</td><td>有什么要求（中文、简洁、一页内）</td></tr><tr><td>忌口</td><td>有什么别做（别编数据、别用英文）</td></tr></tbody></table><p><strong>你说得越像点菜，我做得越像你想吃的。</strong></p><h2 id="万能点菜公式-记住这-4-句" tabindex="-1">万能点菜公式（记住这 4 句） <a class="header-anchor" href="#万能点菜公式-记住这-4-句" aria-label="Permalink to &quot;万能点菜公式（记住这 4 句）&quot;">​</a></h2><p>写任务的时候，按这 4 句话填空就行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 我想要：{什么结果}</span></span>
<span class="line"><span>2. 资料在：{哪个文件/文件夹}</span></span>
<span class="line"><span>3. 要求是：{格式、长度、风格}</span></span>
<span class="line"><span>4. 咋算好：{怎么检查做对了}</span></span></code></pre></div><h3 id="例子-模糊-vs-清楚" tabindex="-1">例子：模糊 vs 清楚 <a class="header-anchor" href="#例子-模糊-vs-清楚" aria-label="Permalink to &quot;例子：模糊 vs 清楚&quot;">​</a></h3><p>❌ 模糊版：&quot;帮我把报告弄一下。&quot;</p><p>✅ 清楚版：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想要：一份 Q3 工作总结报告</span></span>
<span class="line"><span>资料在：data 文件夹里的销售数据</span></span>
<span class="line"><span>要求是：中文、一页以内、开头先写结论</span></span>
<span class="line"><span>咋算好：数字跟数据文件对得上，我不用再改</span></span></code></pre></div><p>看出来区别了吗？<strong>模糊版只能靠猜，清楚版一次做对。</strong></p><h2 id="三个-开口就加分-的小习惯" tabindex="-1">三个&quot;开口就加分&quot;的小习惯 <a class="header-anchor" href="#三个-开口就加分-的小习惯" aria-label="Permalink to &quot;三个&quot;开口就加分&quot;的小习惯&quot;">​</a></h2><ol><li><p><strong>先说结果，再说过程</strong> &quot;我想要一份报告&quot; → 再补资料和要求。</p></li><li><p><strong>一次只说一件事</strong> 别&quot;帮我做 A，顺便把 B 也改了，还有 C&quot;。 做完一件，再说下一件。</p></li><li><p><strong>做完一定检查</strong> 别直接说&quot;好的&quot;就结束。花 30 秒看一眼： &quot;数字对吗？格式对吗？有没有缺的？&quot; 不对就说&quot;这里改一下&quot;——这很正常，不丢人。</p></li></ol><h2 id="实战-现在就练一句" tabindex="-1">实战：现在就练一句 <a class="header-anchor" href="#实战-现在就练一句" aria-label="Permalink to &quot;实战：现在就练一句&quot;">​</a></h2><p>打开对话，把下面这句话里的 <code>{ }</code> 换成你的事，发给我：</p>`,18),a("blockquote",null,[a("p",{你觉得怎么算做好:""},'我想要：{一件你想让我做的事} 资料在：{如果有，写位置；没有就写"没有"} 要求是：{你的要求} 咋算好：')],-1),a("h2",{id:"接下来",tabindex:"-1"},[p("接下来 "),a("a",{class:"header-anchor",href:"#接下来","aria-label":'Permalink to "接下来"'},"​")],-1),a("p",null,"👉 [第 3 课：我能帮你干啥](第3课 我能帮你干啥：生活中的例子.md) —— 看看同事能帮你干什么活。",-1)])])}const b=s(l,[["render",r]]);export{q as __pageData,b as default};
